        for (_, j) in doc.get("jobs").unwrap().entries() {
            if j.get("steps").is_some() {
                for s in steps(j) {
                    if text(s, "uses") == Some("./.github/actions/select-ci-runners") {
                        if text(s, "id") == Some("sentinel_policy") {
