            .unwrap()
            .get("inputs")
            .unwrap()
            .get("use_depot")
            .is_some()
    );
    let selectors = doc
        .get("jobs")
        .unwrap()
        .entries()
        .iter()
        .filter_map(|(_, j)| j.get("steps").map(|_| j))
        .flat_map(steps)
        .filter(|s| text(s, "uses") == Some("./.github/actions/select-ci-runners"))
        .count();
