    assert!(position(validation) < position(install) && position(install) < position(package));
    let Node::Seq(rows) = j
        .get("strategy")
        .unwrap()
        .get("matrix")
        .unwrap()
        .get("include")
        .unwrap()
    else {
        panic!("matrix")
    };
    let cuda = rows
        .iter()
        .filter(|r| text(r, "backend") == Some("cuda"))
